settings.custom_liquid:
{% comment %}
  Hidden One-Time Purchase Reveal Block
  Paste inside a Custom Liquid block on the product page.
{% endcomment %}

{% assign current_variant = product.selected_or_first_available_variant %}
{% assign one_time_price = current_variant.price | money %}

{% if current_variant.selling_plan_allocations.size > 0 %}
  {% assign subscription_allocation = current_variant.selling_plan_allocations.first %}
  {% assign subscription_price = subscription_allocation.price | money %}
  {% assign selling_plan_id = subscription_allocation.selling_plan.id %}
{% else %}
  {% assign subscription_price = current_variant.price | times: 0.8 | money %}
  {% assign selling_plan_id = blank %}
{% endif %}

<div 
  id="mh-purchase-toggle-{{ section.id }}" 
  class="mh-purchase-toggle"
  data-variant-id="{{ current_variant.id }}"
  data-selling-plan-id="{{ selling_plan_id }}"
>

  <!-- SUBSCRIPTION BUTTON -->
  <button type="button" class="mh-main-sub-btn">
    Start now&nbsp;&nbsp; - &nbsp;&nbsp;{{ subscription_price }}
  </button>

  <p class="mh-refill-note">
    *Refills {{ subscription_price }}, change, skip or cancel anytime.
  </p>

  <div class="mh-icons-row">
    <span>✓ Express Shipping</span>
    <span>✓ 100-Days Return</span>
    <span>✓ Scheduled Refills</span>
  </div>

  <!-- ONE TIME PURCHASE LINK -->
  <button type="button" class="mh-one-time-link">
    Prefer one-time purchase? {{ one_time_price }} (no gift).
  </button>

  <!-- HIDDEN ONE TIME PURCHASE BLOCK -->
  <div class="mh-one-time-hidden" hidden>

    <div class="mh-one-time-card">
      <div class="mh-card-top">
        <div class="mh-radio-selected"></div>

        <div class="mh-card-title-wrap">
          <h3>Shower Head Only</h3>

          <ul>
            <li>Shower Head + Filter set</li>
            <li class="mh-crossed">Welcome gift</li>
            <li class="mh-crossed">Loyalty benefits + exclusive offers</li>
          </ul>
        </div>

        <div class="mh-card-price">
          {{ one_time_price }}
        </div>
      </div>
    </div>

    <!-- ONE-TIME BUTTON -->
    <button type="button" class="mh-one-time-btn">
      Start now&nbsp;&nbsp; - &nbsp;&nbsp;{{ one_time_price }}
    </button>

    <div class="mh-icons-row mh-one-time-icons">
      <span>✓ Express Shipping</span>
      <span>✓ 100-Days Return</span>
    </div>

  </div>
</div>

<style>
  .mh-purchase-toggle {
    width: 100%;
    max-width: 760px;
    margin: 20px auto 0;
    font-family: inherit;
    text-align: center;
  }

  .mh-main-sub-btn,
  .mh-one-time-btn {
    width: 100%;
    border: none;
    background: #222;
    color: #fff;
    font-size: 28px;
    font-weight: 400;
    letter-spacing: 0.3px;
    border-radius: 999px;
    padding: 28px 24px;
    cursor: pointer;
    transition: all 0.25s ease;
  }

  .mh-main-sub-btn:hover,
  .mh-one-time-btn:hover {
    transform: translateY(-2px);
    opacity: 0.92;
  }

  .mh-refill-note {
    margin: 26px 0 22px;
    font-size: 24px;
    line-height: 1.4;
    color: #222;
  }

  .mh-icons-row {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 34px;
    flex-wrap: wrap;
    margin: 0 0 48px;
    font-size: 15px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #222;
  }

  .mh-icons-row span {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    white-space: nowrap;
  }

  .mh-one-time-link {
    background: none;
    border: none;
    padding: 0;
    margin: 0 auto 28px;
    color: #9a9a9a;
    font-size: 24px;
    text-decoration: underline;
    cursor: pointer;
    font-family: inherit;
  }

  .mh-one-time-link:hover {
    color: #222;
  }

  .mh-one-time-hidden {
    margin-top: 20px;
    animation: mhFadeIn 0.25s ease forwards;
  }

  .mh-one-time-card {
    background: #f4f3ef;
    border-radius: 22px;
    padding: 34px 40px;
    margin-bottom: 40px;
    text-align: left;
  }

  .mh-card-top {
    display: grid;
    grid-template-columns: 34px 1fr auto;
    gap: 26px;
    align-items: flex-start;
  }

  .mh-radio-selected {
    width: 28px;
    height: 28px;
    border: 3px solid #222;
    border-radius: 50%;
    position: relative;
    margin-top: 4px;
  }

  .mh-radio-selected:after {
    content: "";
    width: 16px;
    height: 16px;
    background: #222;
    border-radius: 50%;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }

  .mh-card-title-wrap h3 {
    margin: 0 0 24px;
    font-size: 28px;
    line-height: 1.1;
    font-weight: 800;
    color: #222;
  }

  .mh-card-title-wrap ul {
    list-style: none;
    padding: 0;
    margin: 0;
  }

  .mh-card-title-wrap li {
    font-size: 23px;
    line-height: 1.45;
    color: #222;
    margin-bottom: 4px;
  }

  .mh-card-title-wrap li:before {
    content: "✓";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border: 1.8px solid #222;
    border-radius: 50%;
    font-size: 12px;
    margin-right: 8px;
    vertical-align: middle;
  }

  .mh-crossed {
    text-decoration: line-through;
  }

  .mh-card-price {
    font-size: 30px;
    font-weight: 800;
    color: #222;
    white-space: nowrap;
  }

  .mh-one-time-btn {
    margin-bottom: 46px;
  }

  .mh-one-time-icons {
    margin-bottom: 0;
  }

  @keyframes mhFadeIn {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @media screen and (max-width: 749px) {
    .mh-purchase-toggle {
      max-width: 100%;
    }

    .mh-main-sub-btn,
    .mh-one-time-btn {
      font-size: 20px;
      padding: 22px 18px;
    }

    .mh-refill-note {
      font-size: 17px;
      margin: 20px 0;
    }

    .mh-icons-row {
      gap: 16px;
      font-size: 12px;
      margin-bottom: 34px;
    }

    .mh-one-time-link {
      font-size: 17px;
    }

    .mh-one-time-card {
      padding: 26px 22px;
      border-radius: 18px;
    }

    .mh-card-top {
      grid-template-columns: 28px 1fr;
      gap: 16px;
    }

    .mh-card-price {
      grid-column: 2;
      font-size: 24px;
      margin-top: 10px;
    }

    .mh-card-title-wrap h3 {
      font-size: 22px;
      margin-bottom: 18px;
    }

    .mh-card-title-wrap li {
      font-size: 17px;
    }
  }
</style>

<script>
  document.addEventListener("DOMContentLoaded", function () {
    const root = document.getElementById("mh-purchase-toggle-{{ section.id }}");
    if (!root) return;

    const revealLink = root.querySelector(".mh-one-time-link");
    const oneTimeBlock = root.querySelector(".mh-one-time-hidden");
    const subButton = root.querySelector(".mh-main-sub-btn");
    const oneTimeButton = root.querySelector(".mh-one-time-btn");

    const variantId = root.dataset.variantId;
    const sellingPlanId = root.dataset.sellingPlanId;

    revealLink.addEventListener("click", function () {
      oneTimeBlock.hidden = false;
      revealLink.style.display = "none";
    });

    function addToCart(isSubscription) {
      const payload = {
        items: [
          {
            id: Number(variantId),
            quantity: 1
          }
        ]
      };

      if (isSubscription && sellingPlanId) {
        payload.items[0].selling_plan = Number(sellingPlanId);
      }

      fetch("/cart/add.js", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json"
        },
        body: JSON.stringify(payload)
      })
      .then(function (res) {
        if (!res.ok) throw new Error("Add to cart failed");
        return res.json();
      })
      .then(function () {
        window.location.href = "/cart";
      })
      .catch(function (error) {
        console.error(error);
        alert("Something went wrong. Please try again.");
      });
    }

    subButton.addEventListener("click", function () {
      addToCart(true);
    });

    oneTimeButton.addEventListener("click", function () {
      addToCart(false);
    });
  });
</script>
